mapper.select:
SELECT L.ID, L.PARK_ID, L.EXEC_TIME, L.STAFF_ID, L.STAFF_BADGE, L.STAFF_NAME, L.DEPARTMENT, L.AUTH_ID, L.AUTH_NAME, L.LAST_SNAP_TIME, L.TRIGGER_REASON, CASE WHEN L.RESULT <> 'PROCESSING' THEN L.RESULT WHEN NVL(S.FAIL_COUNT, 0) > 0 THEN 'FAILED' WHEN NVL(S.TASK_COUNT, 0) = 0 OR NVL(S.UNKNOWN_COUNT, 0) > 0 THEN 'UNKNOWN' WHEN NVL(S.PENDING_COUNT, 0) > 0 THEN 'PROCESSING' WHEN NVL(S.TASK_COUNT, 0) > 0 AND NVL(S.SUCCESS_COUNT, 0) = S.TASK_COUNT THEN 'SUCCESS' ELSE 'UNKNOWN' END AS RESULT, L.REMARK, NVL(S.TASK_COUNT, 0) AS TASK_COUNT, NVL(S.SUCCESS_COUNT, 0) AS SUCCESS_COUNT, NVL(S.FAIL_COUNT, 0) AS FAIL_COUNT, NVL(S.PENDING_COUNT, 0) AS PENDING_COUNT, NVL(S.UNKNOWN_COUNT, 0) AS UNKNOWN_COUNT FROM SMT_SECURITY_AUTH_DELETE_LOG L LEFT JOIN ( SELECT T.LOG_ID, COUNT(T.TASK_ID) AS TASK_COUNT, SUM(CASE WHEN (CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.STATUS WHEN T.TASK_SOURCE = 'ISC' THEN I.STATUS ELSE NULL END) = 1 THEN 1 ELSE 0 END) AS SUCCESS_COUNT, SUM(CASE WHEN (CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.STATUS WHEN T.TASK_SOURCE = 'ISC' THEN I.STATUS ELSE NULL END) IN (2, 4, 5) THEN 1 ELSE 0 END) AS FAIL_COUNT, SUM(CASE WHEN (CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.STATUS WHEN T.TASK_SOURCE = 'ISC' THEN I.STATUS ELSE NULL END) IN (0, 3, 6) THEN 1 ELSE 0 END) AS PENDING_COUNT, SUM(CASE WHEN (CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.STATUS WHEN T.TASK_SOURCE = 'ISC' THEN I.STATUS ELSE NULL END) IS NULL OR (CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.STATUS WHEN T.TASK_SOURCE = 'ISC' THEN I.STATUS ELSE NULL END) NOT IN (0, 1, 2, 3, 4, 5, 6) THEN 1 ELSE 0 END) AS UNKNOWN_COUNT FROM SMT_SECURITY_AUTH_DELETE_TASK T LEFT JOIN SMT_DEVICE_TASK N ON T.TASK_SOURCE = 'NORMAL' AND N.ID = T.TASK_ID LEFT JOIN SMT_ISC_DEVICE_TASK I ON T.TASK_SOURCE = 'ISC' AND I.ID = T.TASK_ID GROUP BY T.LOG_ID ) S ON S.LOG_ID = L.ID
AND L.PARK_ID IN
#{parkId}
AND 1 = 0
AND L.PARK_ID = #{query.parkId}
AND L.EXEC_TIME >= #{query.startTime}
AND L.EXEC_TIME < #{query.endTime}
AND L.STAFF_BADGE LIKE CONCAT(CONCAT('%', #{query.staffBadge}), '%')
AND L.STAFF_NAME LIKE CONCAT(CONCAT('%', #{query.staffName}), '%')
AND L.DEPARTMENT LIKE CONCAT(CONCAT('%', #{query.department}), '%')
AND L.AUTH_NAME LIKE CONCAT(CONCAT('%', #{query.authName}), '%')
AND ( CASE WHEN L.RESULT <> 'PROCESSING' THEN L.RESULT WHEN NVL(S.FAIL_COUNT, 0) > 0 THEN 'FAILED' WHEN NVL(S.TASK_COUNT, 0) = 0 OR NVL(S.UNKNOWN_COUNT, 0) > 0 THEN 'UNKNOWN' WHEN NVL(S.PENDING_COUNT, 0) > 0 THEN 'PROCESSING' WHEN NVL(S.TASK_COUNT, 0) > 0 AND NVL(S.SUCCESS_COUNT, 0) = S.TASK_COUNT THEN 'SUCCESS' ELSE 'UNKNOWN' END ) = #{query.result}
ORDER BY L.EXEC_TIME DESC, L.ID DESC

SELECT T.TASK_SOURCE, T.TASK_ID, T.DEVICE_CODE, T.ACTION, CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.STATUS WHEN T.TASK_SOURCE = 'ISC' THEN I.STATUS ELSE NULL END AS STATUS, CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.CODE WHEN T.TASK_SOURCE = 'ISC' THEN I.CODE ELSE NULL END AS CODE, CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.REMARK WHEN T.TASK_SOURCE = 'ISC' THEN I.REMARK ELSE NULL END AS REMARK, CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.CREATE_TIME WHEN T.TASK_SOURCE = 'ISC' THEN I.CREATE_TIME ELSE NULL END AS CREATE_TIME, CASE WHEN T.TASK_SOURCE = 'NORMAL' THEN N.UPDATE_TIME WHEN T.TASK_SOURCE = 'ISC' THEN I.UPDATE_TIME ELSE NULL END AS UPDATE_TIME FROM SMT_SECURITY_AUTH_DELETE_TASK T INNER JOIN SMT_SECURITY_AUTH_DELETE_LOG L ON L.ID = T.LOG_ID LEFT JOIN SMT_DEVICE_TASK N ON T.TASK_SOURCE = 'NORMAL' AND N.ID = T.TASK_ID LEFT JOIN SMT_ISC_DEVICE_TASK I ON T.TASK_SOURCE = 'ISC' AND I.ID = T.TASK_ID WHERE T.LOG_ID = #{logId}
AND L.PARK_ID IN
#{parkId}
AND 1 = 0
ORDER BY T.ID ASC

SELECT L.*
FROM SMT_SECURITY_AUTH_DELETE_LOG L
WHERE L.ID = #{logId}


			AND L.PARK_ID IN

				#{parkId}


		AND 1 = 0
